const e=[{id:"sv-5-426",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"In the book's Lean tools pyramid, which level sits **directly above** 5S workplace organisation?",options:["Standardized work","Kaizen","Visual factory","Kanban"],answer:2,hint:"5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below.",steps:[{title:"Key idea",body:"The book builds the pyramid from the bottom: 5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below."},{title:"Apply",body:"The level resting directly on 5S is the visual factory."}],final:"Visual factory sits directly on 5S → answer **C**",whyWrong:["Incorrect — standardized work is the third level; it needs the visual factory beneath it.","Incorrect — kaizen is the fourth level, sustained by standardized work.","","Incorrect — kanban is the top of the pyramid, sustained by kaizen."],bookRef:"Book p. 502"},{id:"sv-5-427",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"In the book's pyramid, which tool sits on the level **immediately above** standardized work and is sustained directly by it?",options:["Kanban","Kaizen","Visual factory","5S workplace organisation"],answer:1,hint:"5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below.",steps:[{title:"Key idea",body:"The book: you cannot sustain kaizen without standardized work, and you cannot sustain kanban without kaizen."},{title:"Apply",body:"The level resting directly on standardized work is kaizen."}],final:"Kaizen rests on standardized work → answer **B**",whyWrong:["Incorrect — kanban is the top level, sustained directly by kaizen.","","Incorrect — the visual factory sits below standardized work and supports it.","Incorrect — 5S is the base of the pyramid, well below standardized work."],bookRef:"Book p. 502"},{id:"sv-5-428",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"Why does the book open the Control phase with **Lean controls**?",options:["To find the root causes that the Analyze phase did not confirm","To replace statistical process control on the critical X's","To stabilise the process and sustain the gains by removing waste (muda)","To calculate the final financial benefit of the project"],answer:2,hint:"Control is about holding the gains, not finding new causes.",steps:[{title:"Key idea",body:"The book introduces Lean controls as tools that **stabilise** a process and **sustain** the project by removing muda, so the Belt is not used as a firefighter."},{title:"Eliminate look-alikes",body:"Root-cause work, SPC and financial validation are other activities with other tools."}],final:"Lean controls stabilise and sustain by removing muda → answer **C**",whyWrong:["Incorrect — root causes are verified in Analyze; Lean controls hold the improved state.","Incorrect — Lean controls work alongside SPC and the control plan; they do not replace them.","","Incorrect — verifying financial impact is a separate Control step done with Finance."],bookRef:"Book pp. 501–502"},{id:"sv-5-429",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"Which statement about 5S in the Control phase, compared with 5S in Define, is CORRECT?",options:["In Control 5S is repeated as a full red-tag event every month","In Control only Sorting and Shining are applied","5S belongs only to Define and is not used as a control","In Control the emphasis shifts to standards and sustaining, to hold the improved state"],answer:3,hint:"What does Control need from 5S once the project team leaves?",steps:[{title:"Key idea",body:"In Define, 5S organises the area and exposes waste. In Control it becomes a **control method**: standards, visual controls, audits and discipline keep the area from sliding back."},{title:"Eliminate look-alikes",body:"Monthly clean-ups, partial 5S and 'Define only' all miss the sustaining role."}],final:"Control emphasises Standardize and Sustain → answer **D**",whyWrong:["Incorrect — repeating clean-up events is a sign the controls have failed, not the control itself.","Incorrect — all five S's apply; the sustaining S's get the emphasis in Control.","Incorrect — the book reviews 5S in Control specifically as a control method.",""],bookRef:"Book pp. 501–503"},{id:"sv-5-430",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"According to the book, what often causes **outliers** in a project metric that 5S can help remove?",options:["Normal common-cause variation within a stable process","Different amounts of waste between people, machines or procedures","Plotting too many subgroups on the control chart","Rounding values when the data are recorded"],answer:1,hint:"5S removes waste; why would waste create outliers?",steps:[{title:"Key idea",body:"The book says outliers often come from **different amounts of waste** between people, machines or procedures. Organising the workplace removes those differences."},{title:"Eliminate look-alikes",body:"Common-cause variation, subgroup count and rounding are not sources that 5S addresses."}],final:"Outliers ← uneven waste between people, machines or procedures → answer **B**",whyWrong:["Incorrect — common-cause variation stays within the limits; outliers point to something different between sources.","","Incorrect — the number of subgroups does not create outliers in the metric.","Incorrect — rounding reduces resolution; it does not produce outliers that 5S would fix."],bookRef:"Book pp. 501–502"},{id:"sv-5-431",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"What is the PRIMARY aim of using 5S as a control method at the end of a project?",options:["To identify the vital few X's for the improvement","To estimate the cost of poor quality before the project starts","To stop the improved workplace drifting back, so the gains are sustained","To validate the measurement system used for the project Y"],answer:2,hint:"Which phase is this, and what is that phase for?",steps:[{title:"Key idea",body:"In Control, 5S is a **control method**: it keeps the workplace organised so the project gains do not slowly disappear."},{title:"Eliminate look-alikes",body:"The other options are Define, Measure and Analyze activities."}],final:"5S as control = sustain the gains → answer **C**",whyWrong:["Incorrect — finding the vital few X's is Analyze work.","Incorrect — COPQ is estimated in Define to justify the project.","","Incorrect — measurement system analysis is done in Measure."],bookRef:"Book pp. 501–503"},{id:"sv-5-432",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Which Japanese term matches the 5S step **Shining**?",options:["Seiketsu","Seiri","Seiso","Shitsuke"],answer:2,hint:"Seiri, Seiton, Seiso, Seiketsu, Shitsuke = steps 1 to 5.",steps:[{title:"Key idea",body:"The book lists: 1 Seiri = Sorting, 2 Seiton = Straightening, 3 **Seiso = Shining**, 4 Seiketsu = Standardizing, 5 Shitsuke = Sustaining."},{title:"Apply",body:"Shining is step 3, Seiso."}],final:"Shining = Seiso → answer **C**",whyWrong:["Incorrect — Seiketsu is Standardizing, the fourth S.","Incorrect — Seiri is Sorting, the first S.","","Incorrect — Shitsuke is Sustaining, the fifth S."],bookRef:"Book p. 503"},{id:"sv-5-433",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"During Sorting, items are placed in groups. Which group must be **disposed of immediately**?",options:["Unknown","Unlabelled","Useful","Useless"],answer:3,hint:"The three Sort groups are useful, useless and unknown.",steps:[{title:"Key idea",body:"Book: **useful** → keep and store by frequency; **useless** → dispose of immediately; **unknown** → hold for a set time, then remove if unused."},{title:"Apply",body:"Only the useless group goes at once."}],final:"Useless → dispose of immediately → answer **D**",whyWrong:["Incorrect — unknown items are held for a set period and removed only if nobody uses them.","Incorrect — 'unlabelled' is not one of the book's three Sort groups.","Incorrect — useful items are kept and stored by how often they are used.",""],bookRef:"Book p. 504"},{id:"sv-5-434",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"How does the book advise a team to tackle the removal of unneeded items during Sorting?",options:["By starting with the largest and most expensive items, so the biggest gain comes first","By removing nothing until every area of the site has been sorted","By starting with the easiest items and tagging those that cannot be removed at once","By asking each person to keep whatever they believe they may need"],answer:2,hint:"Book advice on Sort: one area, the easiest items first, tags for the rest.",steps:[{title:"Key idea",body:"The book says start in one area, **always start with the easiest items**, and **tag** items that cannot be removed immediately for later removal."},{title:"Eliminate look-alikes",body:"Starting big, waiting for the whole site or keeping everything all break that advice."}],final:"Easiest first; tag what cannot go yet → answer **C**",whyWrong:["Incorrect — the book says always start with the easiest items, not the hardest or largest.","Incorrect — the book starts in one area and spreads step by step; it does not wait for the whole site.","","Incorrect — keeping 'just in case' items is exactly what Sorting is meant to stop."],bookRef:"Book p. 504"},{id:"sv-5-435",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Under ABC storage, where should a **C item** (used monthly or quarterly) be kept?",options:["Within arm's reach of the workstation","On a nearby shelf or cabinet, off the work surface","On the work surface, clearly labelled","In a remote location a few minutes away"],answer:3,hint:"A = daily, B = weekly, C = monthly or quarterly; distance grows with rarity.",steps:[{title:"Key idea",body:"Book ABC storage: **A** daily → arm's reach; **B** weekly → nearby; **C** monthly or quarterly → remote, a few minutes away."},{title:"Apply",body:"A C item goes to the remote location."}],final:"C item → remote location → answer **D**",whyWrong:["Incorrect — arm's reach is for A items, used daily or several times a day.","Incorrect — a nearby shelf or cabinet is for B items, used weekly.","Incorrect — the work surface is kept for daily items only, never for monthly ones.",""],bookRef:"Book pp. 505–506"},{id:"sv-5-436",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Which practice belongs to the **Straightening** step?",options:["Holding unknown items for a set period before removing them","Storing things that are used together in the same place","Giving each person a cleaning area on a layout map","Running a scheduled audit against a checklist"],answer:1,hint:"Straightening = a place for everything, everything in its place.",steps:[{title:"Key idea",body:"The book's Straightening rules: things used together are **stored together**; use labels, tape, floor marks and shadow outlines; shared items go to a central place."},{title:"Eliminate look-alikes",body:"The other options belong to Sort, Shine and Sustain."}],final:"Store together what is used together = Straightening → answer **B**",whyWrong:["Incorrect — holding unknown items is part of Sorting.","","Incorrect — assigning cleaning areas belongs to Shining.","Incorrect — scheduled audits are a Sustaining tool."],bookRef:"Book p. 506"},{id:"sv-5-437",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"What does the book mean by **mess prevention** in the Shining step?",options:["Removing every item that is not needed for current work","Stopping litter and scrap from reaching the floor in the first place","Painting floor lines so that walkways stay clear","Auditing cleanliness at the end of every shift"],answer:1,hint:"Prevention acts at the source, before cleaning is needed.",steps:[{title:"Key idea",body:"The book stresses that Shining is not only cleaning: find ways to **prevent mess** so litter and scrap never reach the floor."},{title:"Eliminate look-alikes",body:"Sorting, floor lines and audits are other 5S activities."}],final:"Mess prevention = stop dirt at the source → answer **B**",whyWrong:["Incorrect — removing unneeded items is Sorting.","","Incorrect — floor lines are a Straightening and Standardizing visual control.","Incorrect — audits detect mess after it happens; prevention stops it arising."],bookRef:"Book p. 507"},{id:"sv-5-438",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Which tools does the book name for the **Sustaining** step?",options:["Red tags, a holding area and disposal lists","Shadow outlines, labels and floor tape","Schedules and checklists, regular audits and committed leaders","Cleaning maps and mess-prevention guards"],answer:2,hint:"Sustaining is discipline: how do you make sure the habit continues?",steps:[{title:"Key idea",body:"The book: Sustaining is the discipline behind all the other S's. Its tools are **schedules and checklists**, regular audits and leaders who keep the habit alive."},{title:"Eliminate look-alikes",body:"Each other option is the toolset of a different S."}],final:"Sustaining = schedules, checklists, audits, leadership → answer **C**",whyWrong:["Incorrect — red tags and holding areas are Sorting tools.","Incorrect — shadow outlines and labels are Straightening tools.","","Incorrect — cleaning maps and mess prevention belong to Shining."],bookRef:"Book p. 508"},{id:"sv-5-439",phase:5,topic:"5.1.1",qtype:"concept",difficulty:3,stem:"Which statement about the **Standardizing** step of 5S is CORRECT?",options:["It means writing a new SOP for every step of the process","It is the first S, applied before any items are sorted","It is the habit of practising 5S until it becomes a way of life","It sets the rules and visual controls that keep the first three S's in place"],answer:3,hint:"Standardizing protects the results of S1–S3.",steps:[{title:"Key idea",body:"The book: Standardizing keeps the workplace at a level that makes problems obvious, using **visual controls** and standard methods, so the first three S's stay in place."},{title:"Eliminate look-alikes",body:"Process SOPs are standard work, 'first S' is Sorting, and habit is Sustaining."}],final:"Standardizing = rules and visual controls for S1–S3 → answer **D**",whyWrong:["Incorrect — a common trap: Standardizing keeps Sort, Straighten and Shine in place; it is not a process SOP.","Incorrect — Standardizing is the fourth S; Sorting comes first.","Incorrect — that describes Sustaining, the fifth S.",""],trap:"Standardizing is not 'write an SOP for the process'.",bookRef:"Book p. 507"},{id:"sv-5-440",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"According to the book, what should a **visual factory** let even a newly hired supervisor see at a glance?",options:["Inventory levels, extra tools, scrap and downtime","The root causes of each defect type","The financial savings achieved by the project","The capability indices of each process step"],answer:0,hint:"A visual factory shows the current state of the workplace to anyone.",steps:[{title:"Key idea",body:"The book says a visual factory lets even a new supervisor see **inventory levels, extra tools, scrap and downtime** at a glance."},{title:"Eliminate look-alikes",body:"Root causes, savings and capability indices need analysis, not a glance."}],final:"Visual factory shows inventory, tools, scrap, downtime → answer **A**",whyWrong:["","Incorrect — root causes are found with Analyze tools; a visual factory shows current status.","Incorrect — savings are validated by Finance; they are not what the shop floor shows at a glance.","Incorrect — capability indices come from a capability study, not from visual management."],bookRef:"Book p. 508"},{id:"sv-5-441",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Which is an example of **visual management** given in the book's control-plan chapter?",options:["A Gage R&R report filed in the quality system","Empty bins being returned when stock needs replenishing","A regression model saved with the project files","An FMEA spreadsheet reviewed once a year"],answer:1,hint:"Visual management is a signal anyone in the area can see or hear.",steps:[{title:"Key idea",body:"The book lists visual management such as **empty bins returned for replenishment** and red/yellow/green reports, and notes it can be audible too. 5S is necessary for it."},{title:"Eliminate look-alikes",body:"Reports, models and spreadsheets are hidden in files."}],final:"Empty bins returned = visual management signal → answer **B**",whyWrong:["Incorrect — a filed report is documentation; nobody on the floor sees it at a glance.","","Incorrect — a saved model is analysis output, not a visible signal in the workplace.","Incorrect — an annual spreadsheet review is a document control, not a visual signal."],bookRef:"Book p. 570"},{id:"sv-5-442",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"How does the book define **standardized work**?",options:["The method chosen by a majority vote of the operators","The fastest method recorded by the supervisor during a time study","The one best way to do an operation, agreed by general consensus of those doing it","The procedure written by engineering and issued to operators"],answer:2,hint:"Book wording: 'one best way… general consensus (not majority rules)'.",steps:[{title:"Key idea",body:"Standardized work is the **one best way** to perform an operation, set by **general consensus** of those who do it, not by majority rule."},{title:"Eliminate look-alikes",body:"Majority vote, a supervisor's time study and an engineering-issued procedure all miss consensus."}],final:"One best way by consensus → answer **C**",whyWrong:["Incorrect — the book says consensus, explicitly 'not majority rules'.","Incorrect — speed alone is not the criterion, and the supervisor alone does not decide it.","","Incorrect — standard work is agreed with the people who do the job, not issued to them."],trap:"'Majority rules' is the book's own example of what standardized work is NOT.",bookRef:"Book p. 509"},{id:"sv-5-443",phase:5,topic:"5.1.1",qtype:"concept",difficulty:3,stem:"Which statement about **standardized work** is CORRECT?",options:["It can be sustained without a visual factory if the instructions are clear","It is written once by engineering and never revised","It sits below the visual factory in the Lean pyramid","It aims to reduce the standard deviation of results"],answer:3,hint:"What does doing a task the same agreed way do to variation?",steps:[{title:"Key idea",body:"When everyone uses the same best method, results vary less: the book says standardized work **reduces the standard deviation**."},{title:"Eliminate look-alikes",body:"It depends on the visual factory, sits above it, and is revised through kaizen."}],final:"Standardized work reduces variation → answer **D**",whyWrong:["Incorrect — the book says standardized work cannot be sustained without a visual factory.","Incorrect — standard work is the current best way; it is updated as kaizen finds a better one.","Incorrect — standardized work sits above the visual factory, which supports it.",""],bookRef:"Book p. 509"},{id:"sv-5-444",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"During Straightening, where does the book say **shared items** should be kept?",options:["In a central location","At the desk of the person who uses them most","In the remote C-storage area","In the red-tag holding area"],answer:0,hint:"Shared items must be reachable by everyone who uses them.",steps:[{title:"Key idea",body:"The book's Straightening rules say **shared items go to a central location**."},{title:"Eliminate look-alikes",body:"A personal desk, remote C storage and the red-tag area all suit other items."}],final:"Shared items → central location → answer **A**",whyWrong:["","Incorrect — a personal desk hides shared items from the others who need them.","Incorrect — C storage is for items used monthly or quarterly, not for frequently shared items.","Incorrect — the red-tag area holds items awaiting removal, not items in use."],bookRef:"Book p. 506"},{id:"sv-5-445",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"What distinguishes **kaikaku** from **kaizen**?",options:["Kaikaku is continuous, incremental improvement; kaizen is radical, breakthrough change","Kaikaku is radical, breakthrough change; kaizen is continuous, incremental improvement","Kaikaku is the 5S audit; kaizen is the visual factory","Kaikaku is a pull signal; kaizen is a push schedule"],answer:1,hint:"Kai = change; zen = good (small steps); kaku = reform (big step).",steps:[{title:"Key idea",body:"**Kaizen** is continuous improvement in small steps; **kaikaku** is a radical, breakthrough change. The book places kaizen as the fourth level of the pyramid."},{title:"Eliminate look-alikes",body:"The reversed option swaps them; the others confuse the terms with audits or kanban."}],final:"Kaikaku = breakthrough; kaizen = incremental → answer **B**",whyWrong:["Incorrect — this reverses the two terms.","","Incorrect — audits and the visual factory are other Lean controls, not these two terms.","Incorrect — the pull signal is kanban; neither term describes push or pull."],bookRef:"Book p. 510"},{id:"sv-5-446",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"According to the book, what decides **how far up the Lean pyramid** a project must go to be sustained?",options:["The number of team members","The baseline sigma level","The project scope","The preference of the Champion"],answer:2,hint:"A small fix and a flow redesign need different amounts of control.",steps:[{title:"Key idea",body:"The book says **project scope dictates** how far up the ladder you go: a small fix may need only 5S and visual controls; a flow redesign may need standard work and kanban."},{title:"Eliminate look-alikes",body:"Team size, sigma level and preference are not the book's criterion."}],final:"Scope dictates the height on the pyramid → answer **C**",whyWrong:["Incorrect — team size does not determine which controls the process needs.","Incorrect — the baseline sigma level describes performance, not how many control levels are needed.","","Incorrect — the book ties the choice to scope, not to personal preference."],bookRef:"Book p. 513"},{id:"sv-5-447",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Which statement about the strength of a 5S programme is CORRECT, according to the book?",options:["It depends mainly on the size of the initial clean-up budget","It is guaranteed once the first audit scores 100%","It depends on using the Japanese name for each step","It depends on the commitment of employees and the company to maintain it"],answer:3,hint:"What keeps 5S alive after the event?",steps:[{title:"Key idea",body:"The book says the strength of 5S is **contingent on the commitment** of employees and the company to maintain it."},{title:"Eliminate look-alikes",body:"Budget, one audit result and Japanese names do not sustain it."}],final:"5S strength = commitment to maintain it → answer **D**",whyWrong:["Incorrect — money buys a clean-up, but it does not keep the standard in place.","Incorrect — one perfect audit says nothing about whether the standard will hold.","Incorrect — the book advises using the English words, which are easier to remember.",""],bookRef:"Book p. 503"},{id:"sv-5-448",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"Which S is the **last** of the three workplace actions in 5S?",options:["Shining","Sorting","Standardizing","Straightening"],answer:0,hint:"Workplace actions = S1 to S3; sustaining actions = S4 and S5.",steps:[{title:"Key idea",body:"The book: the first three S's (Sort, Straighten, Shine) are **workplace actions**; the last two (Standardize, Sustain) are **sustaining actions**."},{title:"Apply",body:"The third workplace action is Shining."}],final:"Third workplace action = Shining → answer **A**",whyWrong:["","Incorrect — Sorting is the first workplace action.","Incorrect — Standardizing is the first of the two sustaining actions.","Incorrect — Straightening is the second workplace action."],bookRef:"Book p. 503"},{id:"sv-5-449",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"Why is a per-S breakdown of a 5S audit more useful than the total score alone?",options:["It shows which S is slipping, so the action can be targeted","It removes the need for a response rule","It makes the total score statistically significant","It allows the audit to be done less often"],answer:0,hint:"A good total can hide one weak S.",steps:[{title:"Key idea",body:"The total shows the trend; the **per-S breakdown** shows where to act. A healthy total can hide a weak Sustain score that predicts decay."},{title:"Eliminate look-alikes",body:"The breakdown does not replace response rules, test significance or reduce frequency."}],final:"Per-S breakdown locates the weak S → answer **A**",whyWrong:["","Incorrect — a breakdown shows where to act; a response rule still decides when to act.","Incorrect — audit scores are not a hypothesis test; significance is not the point.","Incorrect — more detail per audit does not justify fewer audits."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-450",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"Why are auditors **rotated** in a layered 5S audit programme?",options:["So that each audit takes less time to complete","So that scores are not one person's opinion and blind spots are reduced","So that the area can skip its daily self-check","So that the scoring checklist can change at every audit"],answer:1,hint:"What goes wrong when the same person always scores the area?",steps:[{title:"Key idea",body:"Rotating auditors, with tight scoring definitions, keeps the score objective, spreads ownership and avoids one person's blind spots."},{title:"Eliminate look-alikes",body:"Rotation does not shorten audits, remove self-checks or change the checklist."}],final:"Rotation = objectivity and ownership → answer **B**",whyWrong:["Incorrect — rotation is about objectivity, not saving time.","","Incorrect — self-checks remain the daily layer; rotation does not replace them.","Incorrect — the checklist must stay stable with tight definitions, or scores cannot be compared."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-451",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"What turns a 5S audit score into a real **control**?",options:["Printing the score in the monthly newsletter","Averaging the score over a full year","A pre-agreed response rule that triggers action when the score slides","Adding more questions to the checklist"],answer:2,hint:"A measurement controls nothing unless someone must act on it.",steps:[{title:"Key idea",body:"A score is a control only when a **response rule** goes with it, for example 'any S below 12 of 20 or two audits below target triggers a countermeasure'."},{title:"Eliminate look-alikes",body:"Publishing, averaging and lengthening the checklist all lack a trigger and an action."}],final:"Score + response rule = control → answer **C**",whyWrong:["Incorrect — publishing a score informs people but does not say what must happen.","Incorrect — a yearly average hides a slide until it is too late to act.","","Incorrect — a longer checklist measures more but still triggers no action."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-452",phase:5,topic:"5.1.1",qtype:"concept",difficulty:3,stem:"A service desk applies 5S to its ticket queue. Which statement about this is CORRECT?",options:["Digital work cannot use 5S because there is no physical workplace","Deleting old tickets once is enough to keep the queue in order","Queue rules belong to Sorting, so they need no audit","Queue rules with an automated weekly score act as a Sustaining control"],answer:3,hint:"Digital 5S: rules (Standardize) plus a scored check (Sustain).",steps:[{title:"Key idea",body:"Service teams turn digital 5S into controls: hygiene **rules** with owners, and an automated **score** that is reviewed. The scored review keeps the discipline going."},{title:"Eliminate look-alikes",body:"5S does apply to digital work; one-off purges and unaudited rules do not sustain it."}],final:"Scored queue rules sustain digital 5S → answer **D**",whyWrong:["Incorrect — queues and knowledge bases decay like benches, so 5S applies to them as well.","Incorrect — a one-off purge is a Sort event; without sustaining controls the queue drifts back.","Incorrect — rules are standards, and standards need audits to be sustained.",""],bookRef:"Syllabus 5.1.1"},{id:"sv-5-453",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"In a 5S control system, what is **leader standard work**?",options:["A written routine of what the leader checks, when, and how they respond","A rule that only leaders may carry out 5S audits","An SOP that the leader writes for each operator task","A list of 5S scores used in annual appraisals"],answer:0,hint:"Standard work applied to the supervisor's own day.",steps:[{title:"Key idea",body:"Leader standard work applies standard work to supervisors: a written routine stating **what they check, how often and what they do** with what they find."},{title:"Eliminate look-alikes",body:"It does not stop others auditing, is not an operator SOP and is not an appraisal tool."}],final:"Leader standard work = the leader's own check routine → answer **A**",whyWrong:["","Incorrect — operators self-check daily; leaders add their own layer, not a monopoly.","Incorrect — task SOPs are standardized work for operators, not the leader's own routine.","Incorrect — appraisal use is not the purpose; the routine keeps leaders looking and responding."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-454",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"Which 5S step is summed up as **'a place for everything, and everything in its place'**?",options:["Shining","Sorting","Standardizing","Straightening"],answer:3,hint:"Which S gives each remaining item a fixed, marked home?",steps:[{title:"Key idea",body:"Straightening (Seiton) gives every item a fixed, marked place using labels, floor tape and shadow outlines."},{title:"Eliminate look-alikes",body:"Sorting comes before it; Shining and Standardizing follow it."}],final:"Place for everything = Straightening → answer **D**",whyWrong:["Incorrect — Shining is cleaning and keeping the area clean.","Incorrect — Sorting decides what stays at all: useful, useless or unknown.","Incorrect — Standardizing sets the rules that keep the first three S's in place.",""],bookRef:"Book p. 506"},{id:"sv-5-455",phase:5,topic:"5.1.1",qtype:"concept",difficulty:3,stem:"Why does the book say standardized work instructions on their own will not create consistency?",options:["Instructions must first be signed off by the Finance department","Without an organised 5S workplace, people cannot follow the instructions consistently","Standardized work is decided by majority vote, so some people will ignore it","Written instructions replace the need for training, so skills drift"],answer:1,hint:"Each level of the pyramid needs the level below it.",steps:[{title:"Key idea",body:"The book's summary says standardized work will not create consistency without an organised (5S) workplace: tools must be available, material must flow and stock must be labelled."},{title:"Eliminate look-alikes",body:"Finance, majority voting and replacing training are not the book's reasons."}],final:"Standard work needs the 5S foundation → answer **B**",whyWrong:["Incorrect — Finance validates savings; it does not approve work instructions.","","Incorrect — standardized work is agreed by consensus, not majority vote.","Incorrect — instructions do not replace training; the issue is the missing 5S foundation."],bookRef:"Book pp. 509, 513"},{id:"sv-5-456",phase:5,topic:"5.1.1",qtype:"concept",difficulty:1,stem:"After Sorting and ABC storage, which items should the workplace **itself** hold?",options:["Every item used at least once a year","Only items bought within the last month","Only items needed on a daily-to-weekly basis","All items that carry a label"],answer:2,hint:"Frequency of use decides location.",steps:[{title:"Key idea",body:"The book says the workplace should only hold items needed on a **daily-to-weekly** basis; monthly or quarterly items go to remote storage."},{title:"Eliminate look-alikes",body:"Yearly use, purchase date and labels are not the book's rule."}],final:"Workplace holds daily-to-weekly items only → answer **C**",whyWrong:["Incorrect — yearly items are C items or candidates for removal, not workplace items.","Incorrect — purchase date says nothing about how often an item is used.","","Incorrect — labelling shows where an item belongs; it does not justify keeping it at the workplace."],bookRef:"Book p. 506"},{id:"sv-5-457",phase:5,topic:"5.1.1",qtype:"concept",difficulty:2,stem:"Which is the BEST way to treat 5S audit scores over time?",options:["Repeat the whole 5S event after every single drop in score","Report only the highest score of each quarter","Stop auditing once three scores in a row meet target","Plot them on a run chart and react to sustained movement, not to one bad week"],answer:3,hint:"Audit scores are data; treat them like any monitored metric.",steps:[{title:"Key idea",body:"Plot the total and each S on a run chart. React to **sustained** signals such as consecutive audits below target or a steady decline."},{title:"Eliminate look-alikes",body:"Over-reaction, selective reporting and stopping audits all weaken the control."}],final:"Run chart + react to sustained signals → answer **D**",whyWrong:["Incorrect — reacting to every drop is over-reaction; one low week may be noise.","Incorrect — reporting only the best score hides decline.","Incorrect — areas drift back when audits stop; meeting target is not a reason to stop.",""],bookRef:"Syllabus 5.1.1"},{id:"sv-5-458",phase:5,topic:"5.1.1",qtype:"statements",difficulty:2,stem:`Which statements about the book's Lean tools pyramid are CORRECT?

1. Kanban sits directly above 5S.
2. 5S workplace organisation is the base of the pyramid.
3. A visual factory cannot be sustained without 5S.
4. Kaizen can be sustained without standardized work.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below.",steps:[{title:"Check each",body:"1 false (kanban is the top level). 2 true. 3 true. 4 false (kaizen needs standardized work)."},{title:"Decide",body:"The true statements are 2 and 3."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: the visual factory sits directly above 5S; kanban is at the top.","","Incorrect — statement 4 is false: kaizen is sustained by standardized work.","Incorrect — statements 1 and 4 are both false."],bookRef:"Book p. 502"},{id:"sv-5-459",phase:5,topic:"5.1.1",qtype:"statements",difficulty:2,stem:`Which statements about visual controls are CORRECT?

1. Visual controls are mainly decoration to motivate staff.
2. A visual factory depends on kanban loops already being in place.
3. A shadow outline shows at once when a tool is missing.
4. Visual management signals can be audible as well as visual.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"A visual control shows the standard so a deviation is obvious.",steps:[{title:"Check each",body:"1 false (they expose deviations). 2 false (visual factory rests on 5S; kanban is higher). 3 true (an empty outline = missing tool). 4 true (the book says visual management can be audible)."},{title:"Decide",body:"The true statements are 3 and 4."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — both statements are false: visual controls expose deviations, and the visual factory rests on 5S, not kanban.","Incorrect — statement 2 is false: kanban sits above the visual factory.","","Incorrect — statement 1 is false: a visual control must expose a deviation so someone acts."],bookRef:"Book pp. 506, 508, 570"},{id:"sv-5-460",phase:5,topic:"5.1.1",qtype:"statements",difficulty:3,stem:`Which statements about running 5S audits as a control are CORRECT?

1. Audit results should be posted where the team can see them.
2. One low audit score proves that the 5S programme has failed.
3. The same auditor should always score the area, to keep results consistent.
4. A response rule states what happens when scores fall.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Audits work as controls when they are visible, objective and tied to a response.",steps:[{title:"Check each",body:"1 true (posting results builds ownership). 2 false (one point is not a trend). 3 false (rotate auditors with tight definitions). 4 true (a response rule makes the score a control)."},{title:"Decide",body:"The true statements are 1 and 4."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: react to sustained signals, not to one data point.","Incorrect — statements 2 and 3 are both false.","Incorrect — statement 3 is false: auditors are rotated so scores are not one person's opinion.",""],bookRef:"Syllabus 5.1.1"},{id:"sv-5-461",phase:5,topic:"5.1.1",qtype:"statements",difficulty:2,stem:`Which statements about Sorting and ABC storage are CORRECT?

1. Useless items are disposed of immediately.
2. Unknown items are held for a set period, then removed if nobody uses them.
3. C items, used monthly or quarterly, are kept within arm's reach.
4. The workplace should hold every item used at least monthly.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Sort: useful / useless / unknown. ABC: daily → arm's reach, weekly → nearby, monthly+ → remote.",steps:[{title:"Check each",body:"1 true. 2 true. 3 false (C items go to a remote location). 4 false (only daily-to-weekly items stay at the workplace)."},{title:"Decide",body:"The true statements are 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: arm's reach is for A items used daily.","Incorrect — statements 3 and 4 are both false.","Incorrect — statement 4 is false: the workplace holds only daily-to-weekly items."],bookRef:"Book pp. 504–506"},{id:"sv-5-462",phase:5,topic:"5.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

According to the book, you cannot sustain a visual factory without [?].`,options:["5S","Kaizen","Kanban","Standardized work"],answer:0,hint:"5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below.",steps:[{title:"Key idea",body:"The visual factory is the second level; the level beneath it is **5S workplace organisation**."},{title:"Eliminate look-alikes",body:"Standardized work, kaizen and kanban are all above the visual factory."}],final:"Visual factory rests on 5S → answer **A**",whyWrong:["","Incorrect — kaizen sits above the visual factory and depends on it, not the reverse.","Incorrect — kanban is the top of the pyramid, far above the visual factory.","Incorrect — standardized work is sustained by the visual factory, not the other way round."],bookRef:"Book pp. 502, 508"},{id:"sv-5-463",phase:5,topic:"5.1.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

[?] (Seiketsu) keeps the workplace at a level that makes problems obvious, using visual controls such as signboards and colour-coding.`,options:["Shining","Sorting","Standardizing","Straightening"],answer:2,hint:"Seiketsu is the fourth S, the first sustaining action.",steps:[{title:"Key idea",body:"The book: **Standardizing (Seiketsu)** maintains orderliness through visual controls (signboards, painted lines, colour-coding) so problems are obvious."},{title:"Eliminate look-alikes",body:"Sorting, Straightening and Shining are the three workplace actions before it."}],final:"Seiketsu = Standardizing → answer **C**",whyWrong:["Incorrect — Shining (Seiso) is cleaning and mess prevention.","Incorrect — Sorting (Seiri) decides which items stay.","","Incorrect — Straightening (Seiton) gives every item a fixed place."],bookRef:"Book p. 507"},{id:"sv-5-464",phase:5,topic:"5.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In ABC storage, items used [?] are kept within arm's reach of the workstation.`,options:["daily","monthly","quarterly","weekly"],answer:0,hint:"The more often it is used, the closer it is kept.",steps:[{title:"Key idea",body:"Book ABC storage: **A = daily** or several times a day → within arm's reach; B = weekly → nearby; C = monthly or quarterly → remote."},{title:"Apply",body:"Arm's reach is for daily items."}],final:"Arm's reach = daily (A items) → answer **A**",whyWrong:["","Incorrect — monthly items are C items, kept in a remote location.","Incorrect — quarterly items are also C items, a few minutes away.","Incorrect — weekly items are B items, kept nearby but off the work surface."],bookRef:"Book pp. 505–506"},{id:"sv-5-465",phase:5,topic:"5.1.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The book says that a Six Sigma project is actually a [?].`,options:["kaikaku","kaizen","kanban","poka-yoke"],answer:1,hint:"Which pyramid level is an improvement project?",steps:[{title:"Key idea",body:"The book places **kaizen** on the fourth level of the pyramid and says a Six Sigma project is actually a kaizen, sustained by standardized work."},{title:"Eliminate look-alikes",body:"Kaikaku, kanban and poka-yoke are other Lean terms."}],final:"Six Sigma project = a kaizen → answer **B**",whyWrong:["Incorrect — kaikaku is radical, breakthrough change, not the pyramid level the book names.","","Incorrect — kanban is a pull signal at the top of the pyramid.","Incorrect — poka-yoke is mistake proofing, a separate Control tool."],bookRef:"Book p. 510"},{id:"sv-5-466",phase:5,topic:"5.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In the Standardizing step, orderliness is maintained by [?] controls such as signboards, painted lines and colour-coding.`,options:["financial","statistical","verbal","visual"],answer:3,hint:"Signboards, lines and colours share one feature: you can see them.",steps:[{title:"Key idea",body:"The book says orderliness in Standardizing is kept by **visual controls**: signboards, painted lines, colour-coding."},{title:"Eliminate look-alikes",body:"Financial, statistical and verbal controls do not show the standard at a glance."}],final:"Signboards, lines, colours = visual controls → answer **D**",whyWrong:["Incorrect — financial controls track money, not workplace order.","Incorrect — statistical controls are SPC charts on process data.","Incorrect — verbal instructions are not visible at a glance and are easily forgotten.",""],bookRef:"Book p. 507"},{id:"sv-5-467",phase:5,topic:"5.1.1",qtype:"not-except",difficulty:3,stem:"The book lists prerequisites for standardized work. Which is NOT one of them?",options:["A kanban loop already running between processes","Required tools available at the workstation","A consistent flow of material","Identified and labelled in-process stock"],answer:0,hint:"Prerequisites come from the levels below, not above.",steps:[{title:"Key idea",body:"The book's prerequisites for standardized work are 5S ones: tools available, consistent material flow, visual alerts of variation, labelled in-process stock."},{title:"Apply",body:"Kanban sits **above** standardized work, so it cannot be a prerequisite for it."}],final:"Kanban is above standard work → NOT a prerequisite → answer **A**",whyWrong:["","Incorrect — available tools is one of the book's 5S-based prerequisites.","Incorrect — a consistent flow of material is a listed prerequisite.","Incorrect — labelled in-process stock is a listed prerequisite."],bookRef:"Book p. 509"},{id:"sv-5-468",phase:5,topic:"5.1.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a level of the book's Lean tools pyramid?",options:["Visual factory","Poka-yoke","Kaizen","Standardized work"],answer:1,hint:"5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below.",steps:[{title:"Key idea",body:"The pyramid has five levels: 5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below."},{title:"Apply",body:"Poka-yoke (mistake proofing) is a separate Control tool and is not a pyramid level."}],final:"Poka-yoke is not in the pyramid → answer **B**",whyWrong:["Incorrect — the visual factory is the second level.","","Incorrect — kaizen is the fourth level.","Incorrect — standardized work is the third level."],bookRef:"Book p. 502"},{id:"sv-5-469",phase:5,topic:"5.1.1",qtype:"not-except",difficulty:1,stem:"Which is NOT a visual control used to maintain the Standardizing step?",options:["Painted floor lines","Colour-coded labels","A monthly cost-of-poor-quality report filed with Finance","Signboards at each work area"],answer:2,hint:"Can a person in the area see it at a glance?",steps:[{title:"Key idea",body:"The book names signboards, painted lines and colour-coding as the visual controls of Standardizing."},{title:"Apply",body:"A report filed with Finance is not visible in the workplace, so it is not a visual control."}],final:"Filed report is not a visual control → answer **C**",whyWrong:["Incorrect — painted lines are one of the book's visual controls.","Incorrect — colour-coding is one of the book's visual controls.","","Incorrect — signboards are one of the book's visual controls."],bookRef:"Book p. 507"},{id:"sv-5-470",phase:5,topic:"5.1.1",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the three groups that items are placed in during Sorting?",options:["Unknown","Urgent","Useful","Useless"],answer:1,hint:"Useful, useless, unknown.",steps:[{title:"Key idea",body:"The book's three Sort groups are **useful**, **useless** and **unknown**."},{title:"Apply",body:"'Urgent' is not one of them."}],final:"Urgent is not a Sort group → answer **B**",whyWrong:["Incorrect — unknown is a Sort group: hold for a set period, then remove if unused.","","Incorrect — useful is a Sort group: keep and store by frequency of use.","Incorrect — useless is a Sort group: dispose of immediately."],bookRef:"Book p. 504"},{id:"sv-5-471",phase:5,topic:"5.1.1",qtype:"not-except",difficulty:3,stem:"A NOC applies 5S controls to its knowledge base (KB). Which is NOT a sustaining control for the KB?",options:["A named owner for every article","Overdue reviews turning amber on the KB dashboard","A weekly automated compliance score","A one-off purge of all articles older than two years"],answer:3,hint:"Sustaining controls work continuously; a one-off event does not.",steps:[{title:"Key idea",body:"Digital 5S controls need owners, visual flags and regular scoring so the KB does not decay."},{title:"Apply",body:"A one-off purge is a Sort event. Without ongoing controls, the KB drifts back."}],final:"One-off purge is not a sustaining control → answer **D**",whyWrong:["Incorrect — named ownership keeps each article maintained over time.","Incorrect — amber flags are a visual control that triggers action.","Incorrect — a weekly score is an audit that sustains the standard.",""],bookRef:"Syllabus 5.1.1"},{id:"sv-5-472",phase:5,topic:"5.1.1",qtype:"not-except",difficulty:1,stem:"5S audit scores in a store room have started to slide. Which is NOT good practice in response?",options:["Re-cleaning the area the night before the next audit","Asking why the standard is not being held","Checking whether new staff have been trained on the standard","Reviewing whether tools or storage locations are missing"],answer:0,hint:"Fix the cause of the slide, not the score.",steps:[{title:"Key idea",body:"When scores slide, treat it like any DMAIC problem: ask **why** the standard is not held (training, tools, demand, realism)."},{title:"Apply",body:"A last-minute clean improves one score but hides the cause, so it is NOT good practice."}],final:"Pre-audit clean-up hides the cause → NOT good practice → answer **A**",whyWrong:["","Incorrect — asking why is the root-cause discipline the response needs.","Incorrect — untrained new staff are a common reason a standard slips.","Incorrect — missing tools or locations make the standard impossible to hold."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-473",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:2,stem:"After a project at a handset repair centre, repair time is mostly stable, but several large outliers keep appearing and the early gains are fading. According to the book, which Lean control should the team apply first?",options:["Introduce a kanban loop for spare parts","5S the project area","Run a kaizen event on the slowest repair step","Write standardized work for each technician"],answer:1,hint:"Outliers and lost gains are the book's signs for one particular tool.",steps:[{title:"Key idea",body:"The book lists **outliers** in the project metric and **loss of initial gains** as signs that the team should 5S the project area."},{title:"Eliminate look-alikes",body:"Kanban, kaizen and standardized work sit higher on the pyramid and need 5S first."}],final:"Outliers + fading gains → 5S the area → answer **B**",whyWrong:["Incorrect — kanban is the top of the pyramid and will backfire without the lower levels.","","Incorrect — kaizen needs standardized work and 5S beneath it.","Incorrect — standard work will not create consistency without an organised workplace."],bookRef:"Book p. 513"},{id:"sv-5-474",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:1,stem:"In a contact-centre team, each agent logs complaints in their own way, and handling times vary widely. The team leader works with the agents to agree the single best way to log a complaint. Which Lean control is being applied?",options:["Visual factory","Kanban","Standardized work","Sorting"],answer:2,hint:"One best way, agreed with the people who do the work.",steps:[{title:"Key idea",body:"Agreeing the **one best way** to do a task by consensus is **standardized work**, which reduces variation in results."},{title:"Eliminate look-alikes",body:"Visual factory, kanban and Sorting do not define a common method."}],final:"Agreed best method = standardized work → answer **C**",whyWrong:["Incorrect — a visual factory makes status visible; it does not define the method.","Incorrect — kanban is a pull signal for starting work.","","Incorrect — Sorting removes unneeded items; it does not agree a method."],bookRef:"Book p. 509"},{id:"sv-5-475",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:1,stem:"A warehouse puts up a large board showing green, yellow or red for each picking zone against target. A light flashes when a zone falls behind. Which Lean control is this?",options:["Standardized work","Kanban","Kaizen","Visual factory"],answer:3,hint:"Status made visible to anyone at a glance.",steps:[{title:"Key idea",body:"Red/yellow/green boards and lights make status and deviations visible to everyone: this is the **visual factory** (visual management)."},{title:"Eliminate look-alikes",body:"Standard work, kanban and kaizen have other purposes."}],final:"Status board and light = visual factory → answer **D**",whyWrong:["Incorrect — standardized work defines the method; it does not display status.","Incorrect — kanban authorises work or replenishment; this board only shows status.","Incorrect — kaizen is an improvement activity, not a status display.",""],bookRef:"Book pp. 508, 570"},{id:"sv-5-476",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:3,stem:"A fibre depot wants to introduce standardized work for van loading. Tools are often missing, material arrives at irregular times, and in-process stock is unlabelled. What does the book imply about this plan?",options:["Standardized work will not hold until 5S and visual controls are in place","Standardized work should start at once, to force the other changes","Kanban should be introduced first, to steady the material flow","The team should go straight to a kaizen event"],answer:0,hint:"Check the book's prerequisites for standardized work against the stem.",steps:[{title:"Key idea",body:"The book's prerequisites for standardized work are available tools, consistent material flow, visual alerts and labelled stock, which are 5S and visual-factory conditions."},{title:"Apply",body:"All three are missing, so the depot must build the lower levels first."},{title:"Eliminate look-alikes",body:"Kanban and kaizen sit even higher on the pyramid."}],final:"Build 5S and visual controls before standard work → answer **A**",whyWrong:["","Incorrect — the book says standard work cannot be sustained without the levels beneath it.","Incorrect — kanban sits at the top and will backfire if introduced this early.","Incorrect — kaizen needs standardized work beneath it, so it cannot come first."],bookRef:"Book pp. 502, 509"},{id:"sv-5-477",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:1,stem:"In a radio-site maintenance van, splicing tools and splice protection sleeves are always used together but are kept in different lockers. The technician moves them into one labelled drawer. Which S is this?",options:["Shining","Sorting","Standardizing","Straightening"],answer:3,hint:"Which S gives items a fixed place, together with what they are used with?",steps:[{title:"Key idea",body:"The book's Straightening rule: things **used together are stored together**, with labels."},{title:"Eliminate look-alikes",body:"Sorting, Shining and Standardizing are the S's before and after it."}],final:"Stored together, labelled = Straightening → answer **D**",whyWrong:["Incorrect — Shining is cleaning and preventing mess.","Incorrect — Sorting decides whether items are kept at all.","Incorrect — Standardizing sets the rules that keep the first three S's in place.",""],bookRef:"Book p. 506"},{id:"sv-5-478",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:2,stem:"In a circuit-board rework area, solder scrap keeps falling on the floor. Instead of sweeping more often, the team fits catch trays under each station so the scrap never reaches the floor. Which 5S idea is this?",options:["Red-tagging, within Sorting","Mess prevention, within Shining","ABC storage, within Straightening","Audit scheduling, within Sustaining"],answer:1,hint:"Stopping dirt at its source rather than cleaning it up.",steps:[{title:"Key idea",body:"The book stresses **mess prevention** in Shining: stop litter and scrap reaching the floor in the first place."},{title:"Eliminate look-alikes",body:"Red-tagging, ABC storage and audits belong to other S's."}],final:"Catch trays = mess prevention in Shining → answer **B**",whyWrong:["Incorrect — red tags mark unneeded items for removal; scrap falling is not a sorting decision.","","Incorrect — ABC storage places items by frequency of use.","Incorrect — audits check the standard; they do not stop scrap reaching the floor."],bookRef:"Book p. 507"},{id:"sv-5-479",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:3,stem:"Project A fixed a labelling error at one packing station. Project B redesigned the flow of orders through three departments. Which statement fits the book's guidance on Lean controls?",options:["Both projects need kanban, because it is the top of the pyramid","Project A needs more pyramid levels, because its scope is smaller","Project B is likely to need controls further up the pyramid than Project A","Neither project needs 5S, because both are now in Control"],answer:2,hint:"The book: project scope dictates how far up the ladder you go.",steps:[{title:"Key idea",body:"The book says **project scope** dictates how far up the pyramid a project must go to be sustained."},{title:"Apply",body:"A one-station fix may need only 5S and visual controls; a three-department flow redesign may need standard work, kaizen and even kanban."},{title:"Eliminate look-alikes",body:"Kanban for all, smaller-needs-more, and no 5S all contradict the book."}],final:"Wider scope → higher on the pyramid → answer **C**",whyWrong:["Incorrect — the book says scope dictates the height; a small fix may need only 5S and visual controls.","Incorrect — this reverses the logic: wider scope needs more levels.","","Incorrect — 5S is the base for every Lean control, including in Control."],bookRef:"Book p. 513"},{id:"sv-5-480",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:3,stem:"A service desk has a rule that no ticket may go more than five days without an update. Every Friday an automated report scores the open queue against the rule and posts the result on the team screen. Which S does the weekly scored report MAINLY represent?",options:["Shining","Sorting","Standardizing","Sustaining"],answer:3,hint:"Separate the rule (standard) from the regular scored check (discipline).",steps:[{title:"Key idea",body:"The **rule** is a standard (Standardizing). The **regular, scored audit** that checks the rule is still followed is a Sustaining tool, like the book's schedules, checklists and audits."},{title:"Apply",body:"The question asks about the weekly scored report, so the answer is Sustaining."}],final:"Regular scored check = Sustaining → answer **D**",whyWrong:["Incorrect — Shining is cleaning; stale data clean-up is the action, not the weekly check.","Incorrect — Sorting removes what is not needed; the report does not remove tickets.","Incorrect — the five-day rule itself is the standard; the scored weekly check is the discipline that sustains it.",""],trap:"Rule = Standardizing; audit of the rule = Sustaining.",bookRef:"Book p. 508"},{id:"sv-5-481",phase:5,topic:"5.1.1",qtype:"scenario",difficulty:3,stem:"A Black Belt finds that one of three billing shifts produces most of the outliers in invoice cycle time. On a walk-through she sees that shift's desks cluttered and forms stored in random drawers. What does the book suggest about this situation?",options:["The outliers prove that the measurement system is not repeatable","The shift should be given a different type of control chart","The outliers should be deleted before process capability is calculated","The outliers may come from different amounts of waste, so the area should be 5S'd"],answer:3,hint:"Book: outliers often come from different amounts of waste between people or procedures.",steps:[{title:"Key idea",body:"The book links outliers to **different amounts of waste** between people, machines or procedures, and lists outliers as a sign that 5S is needed."},{title:"Apply",body:"Clutter and random storage on one shift is that kind of difference, so 5S that area."},{title:"Eliminate look-alikes",body:"MSA, chart changes and deleting data do not address waste."}],final:"Shift-specific outliers + clutter → 5S → answer **D**",whyWrong:["Incorrect — nothing in the stem points to the gauge; the clutter points to waste.","Incorrect — changing the chart does not remove the cause of the outliers.","Incorrect — deleting outliers hides a real cause instead of removing it.",""],bookRef:"Book pp. 501, 513"},{id:"sv-5-482",phase:5,topic:"5.1.1",qtype:"best-action",difficulty:2,stem:"After a successful 5S event, the Black Belt hands the area to the Process Owner with a posted photo standard, a weekly scored audit and a response rule for low scores. Was this an appropriate action?",options:["Yes, because standards, audits and a response rule are what sustain 5S once the team leaves","Yes, because the Process Owner will now repeat the full 5S event every month","No, because 5S audits should be carried out only by the Black Belt","No, because 5S is a Define tool and is not part of the control plan"],answer:0,hint:"What keeps 5S alive after the project closes?",steps:[{title:"Key idea",body:"5S is held in place by **standards + visual controls + audits + discipline**, owned by the process owner."},{title:"Apply",body:"The hand-over gives exactly those elements, so the action was appropriate."}],final:"Hand-over with standard, audit and response rule is appropriate → answer **A**",whyWrong:["","Incorrect — monthly re-runs of the event are a sign of failed controls, not the purpose of the hand-over.","Incorrect — the Process Owner owns sustaining; the Belt moves on to new projects.","Incorrect — the book reviews 5S in Control precisely as a control method."],bookRef:"Book pp. 503, 508"},{id:"sv-5-483",phase:5,topic:"5.1.1",qtype:"best-action",difficulty:3,stem:"A data-centre team's 5S audits show Sorting, Straightening and Shining at target, but Standardizing and Sustaining falling for six weeks. The Black Belt decides to run a new red-tag Sorting event. Was this an appropriate action?",options:["Yes, because every slide in 5S should be fixed by restarting with Sorting","Yes, because red tags also set the standards for the area","No, because the weakness is in the sustaining actions, which need standards, audits and discipline","No, because the audits should be stopped until the scores recover"],answer:2,hint:"Match the remedy to the S that is failing.",steps:[{title:"Key idea",body:"The first three S's are **workplace actions**; the last two are **sustaining actions**."},{title:"Apply",body:"Only S4 and S5 are falling, so the fix is stronger standards, visual controls, audit routines and leadership, not another Sort."}],final:"Sustaining weakness needs sustaining controls, not a new Sort → answer **C**",whyWrong:["Incorrect — the workplace S's are at target; restarting Sorting repairs nothing that is broken.","Incorrect — red tags mark unneeded items; standards are set in Standardizing.","","Incorrect — stopping audits removes the very control that is weak."],bookRef:"Book pp. 503, 507–508"},{id:"sv-5-484",phase:5,topic:"5.1.1",qtype:"best-action",difficulty:3,stem:"A Black Belt wants agents in a contact centre to use one method for refund requests. Two methods are popular, and 55% of agents prefer one of them. What is the BEST way to set the standard?",options:["Work with the agents to reach consensus on the one best method","Adopt the method preferred by the 55% majority","Let each agent keep using their own method","Have the Black Belt choose the faster method alone"],answer:0,hint:"The book: one best way, by general consensus (not majority rules).",steps:[{title:"Key idea",body:"Standardized work is the one best way agreed by **general consensus** of those doing the work."},{title:"Eliminate look-alikes",body:"Majority vote, individual methods and a Belt's solo choice all miss consensus."}],final:"Consensus, not majority → answer **A**",whyWrong:["","Incorrect — the book says standardized work is by consensus, 'not majority rules'.","Incorrect — keeping individual methods keeps the variation that standard work removes.","Incorrect — a method imposed by one person lacks the consensus the book requires."],bookRef:"Book p. 509"},{id:"sv-5-485",phase:5,topic:"5.1.1",qtype:"best-action",difficulty:2,stem:"A store room's response rule says that two consecutive 5S audits below target trigger action. This has just happened. What is the BEST action?",options:["Repeat the whole 5S event, starting again from Sorting","Find out why the standard is not being held and assign a countermeasure owner","Lower the audit target so that the area passes next time","Pause the audits until the area has been re-cleaned"],answer:1,hint:"A response rule exists to trigger root-cause action.",steps:[{title:"Key idea",body:"When the response rule fires, ask **why** the standard is not being held (training, tools, demand, realism) and give the countermeasure an owner."},{title:"Eliminate look-alikes",body:"Re-running the event, moving the target and pausing audits avoid the cause."}],final:"Rule fires → find the cause, assign an owner → answer **B**",whyWrong:["Incorrect — restarting the event treats the symptom without asking why the standard slipped.","","Incorrect — lowering the target hides the problem and weakens the control.","Incorrect — pausing audits removes the control when it is most needed."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-486",phase:5,topic:"5.1.1",qtype:"best-action",difficulty:2,stem:"A Black Belt is asked to sustain an improved order-entry process. She posts a red/yellow/green status board beside the team, so anyone can see whether today's orders are meeting target. Was this an appropriate action?",options:["Yes, because a status board replaces the need for a response plan","Yes, because a visual control shows status and deviations at a glance, so people can respond","No, because visual controls are only for manufacturing floors","No, because status boards belong to the Define phase"],answer:1,hint:"Visual management makes the standard, and any deviation, obvious.",steps:[{title:"Key idea",body:"The book's visual management includes red/yellow/green reports. They let anyone see status at a glance, so a deviation is noticed and acted on."},{title:"Apply",body:"The board is an appropriate visual control; it supports, but does not replace, the response plan."}],final:"Status board is an appropriate visual control → answer **B**",whyWrong:["Incorrect — a board shows the deviation; a response plan still says what to do about it.","","Incorrect — visual management works in offices and IT as well as factories.","Incorrect — visual controls are Control-phase tools that sustain the gains."],bookRef:"Book pp. 508, 570"},{id:"sv-5-487",phase:5,topic:"5.1.1",qtype:"best-action",difficulty:2,stem:"In a field depot, the weekly 5S audit is skipped whenever the team lead is busy, and Sustaining scores are falling. What is the BEST control to add?",options:["Hire a contractor to deep-clean the depot every month","Remove Sustaining from the audit checklist","Build the audit into the leader's standard work at a fixed slot, such as shift handover","Hold a new 5S launch event every quarter"],answer:2,hint:"Sustaining is a leadership routine before it is an operator habit.",steps:[{title:"Key idea",body:"The book's Sustaining tools are schedules, checklists, audits and committed leaders. Fixing the audit into **leader standard work** makes it happen every week."},{title:"Eliminate look-alikes",body:"Outsourced cleaning, a shorter checklist and launch events do not restore the discipline."}],final:"Fix the audit into leader standard work → answer **C**",whyWrong:["Incorrect — a contractor cleans the depot but does not build the team's discipline.","Incorrect — removing the weak item hides the problem.","","Incorrect — repeated launch events are a sign that the sustaining controls are missing."],bookRef:"Book p. 508"},{id:"sv-5-488",phase:5,topic:"5.1.1",qtype:"output",difficulty:2,stem:`A store room's weekly 5S audit totals are shown. The response rule is: *two consecutive audits below target trigger a countermeasure*.

\`\`\`
5S Audit Trend – Store room B        Target = 80%
Week    12    13    14    15    16    17
Total   86%   83%   79%   82%   78%   77%
\`\`\`

In which week does the response rule first fire?`,options:["Week 14","Week 16","Week 15","Week 17"],answer:3,hint:"Look for the first pair of back-to-back results below 80%.",steps:[{title:"Read the output",body:"Below target: week 14 (79%), week 16 (78%), week 17 (77%). Week 15 (82%) breaks the first run."},{title:"Decide",body:"The first two consecutive results below target are weeks 16 and 17, so the rule fires at week 17."}],final:"Weeks 16 and 17 both below 80% → fires at week 17 → answer **D**",whyWrong:["Incorrect — week 14 is below target, but week 15 recovers, so there are not two in a row.","Incorrect — week 16 is the first of two consecutive weeks below target; the rule needs the second.","Incorrect — week 15 is above target (82%).",""],bookRef:"Syllabus 5.1.1"},{id:"sv-5-489",phase:5,topic:"5.1.1",qtype:"output",difficulty:3,stem:`A red-tag log from a Sorting event is shown. The rule is: *unknown items are held for 30 days and removed if nobody has used them*.

\`\`\`
Red-tag log – Test lab           Today = day 41
Tag  Item                 Group     Tagged  Used since tag
 R1  Spare OTDR battery   Unknown   day 5   Yes
 R2  Old patch panel      Unknown   day 8   No
 R3  Spare SFP tray       Unknown   day 25  No
 R4  Cracked monitor      Useless   day 40  No
\`\`\`

Which decision follows the book's Sorting rules?`,options:["Remove R2 and R4 now; keep R1; keep holding R3","Remove R1, R2 and R3 now, because all are unknown","Keep R4 until it has been held for 30 days","Remove R3 now and keep R2 for another 30 days"],answer:0,hint:"Useless → now. Unknown → after the hold period, only if unused.",steps:[{title:"Read the output",body:"R1 was used → useful, keep. R2 tagged day 8, unused, more than 30 days ago → remove. R3 tagged day 25 → still inside its 30 days. R4 useless → remove now."},{title:"Decide",body:"Remove R2 and R4; keep R1; keep holding R3."}],final:"R2 and R4 out, R1 kept, R3 still held → answer **A**",whyWrong:["","Incorrect — R1 has been used, so it is useful; R3 has not yet reached 30 days.","Incorrect — useless items are disposed of immediately, not held.","Incorrect — R3 has been held only since day 25; R2 has passed 30 days unused."],bookRef:"Book p. 504"},{id:"sv-5-490",phase:5,topic:"5.1.1",qtype:"output",difficulty:2,stem:`A usage study for a fibre workshop bench is shown.

\`\`\`
Tool usage – fibre workshop (4-week study)
Item                  Typical use
Cleaver               Several times a day
Power meter           About once a week
Fusion-splicer kit    Every day
OTDR calibration set  Once a quarter
\`\`\`

Which ABC storage plan follows the book's rules?`,options:["All four items at arm's reach, because all are used in the workshop","Cleaver and splicer kit at arm's reach; power meter nearby; calibration set remote","Cleaver at arm's reach; splicer kit and power meter remote; calibration set nearby","Calibration set at arm's reach, because it is the most valuable item"],answer:1,hint:"A = daily → arm's reach; B = weekly → nearby; C = monthly or quarterly → remote.",steps:[{title:"Read the output",body:"Cleaver and splicer kit are daily (A). Power meter is weekly (B). Calibration set is quarterly (C)."},{title:"Decide",body:"A at arm's reach, B nearby, C in a remote location."}],final:"A arm's reach, B nearby, C remote → answer **B**",whyWrong:["Incorrect — the workplace holds only daily-to-weekly items close by; quarterly items go remote.","","Incorrect — the daily splicer kit belongs at arm's reach, and the quarterly set is a C item.","Incorrect — the book stores by frequency of use, not by value."],bookRef:"Book pp. 505–506"},{id:"sv-5-491",phase:5,topic:"5.1.1",qtype:"output",difficulty:3,stem:`Monthly results for an invoicing team are shown. The project closed after month 3; the weekly 5S audits stopped after month 4.

\`\`\`
Invoice cycle time – monthly summary
Month   Mean (h)   Outliers   5S audits done
  1       18.2        1             4
  2       18.0        0             4
  3       18.1        1             4
  4       18.6        2             1
  5       20.4        6             0
  6       22.9        9             0
\`\`\`

Which conclusion is MOST consistent with the book's guidance?`,options:["The process is improving, because the team now spends no time on audits","The outliers show that the measurement system must be replaced","The rising outliers and lost gains are signs that 5S controls are needed again","The mean is still near the baseline, so no action is needed"],answer:2,hint:"Book signs that 5S is needed: outliers and loss of initial gains.",steps:[{title:"Read the output",body:"Months 1–3: mean about 18 h, 0–1 outliers, 4 audits a month. Months 5–6: no audits, outliers 6 and 9, mean 20.4 and 22.9 h."},{title:"Decide",body:"Outliers rising and initial gains fading are the book's signs that 5S is needed. The pattern lines up with the audits stopping, which the team should investigate."}],final:"Outliers + lost gains → reinstate 5S controls → answer **C**",whyWrong:["Incorrect — the mean and outliers are both getting worse since the audits stopped.","Incorrect — nothing in the output points to the measurement system.","","Incorrect — the mean has risen from about 18 h to almost 23 h; the gains are being lost."],bookRef:"Book p. 513"},{id:"sv-5-492",phase:5,topic:"5.1.1",qtype:"output",difficulty:3,stem:`A site's Lean readiness checklist is shown.

\`\`\`
Lean controls readiness – Depot 7
Level                  Status
5S                     In place, audited weekly
Visual factory         In place
Standardized work      Not started
Kaizen                 Not started
Kanban                 Requested by the operations manager
\`\`\`

Based on the checklist, which conclusion is CORRECT?`,options:["Kanban can start now, because 5S and the visual factory are in place","The depot should drop 5S audits, since the visual factory now exists","Kaizen should be skipped, because kanban is the higher level","Kanban cannot be sustained yet; standardized work should be built next"],answer:3,hint:"5S → Visual Factory → Standardized Work → Kaizen → Kanban (bottom to top); each level is sustained by the one below.",steps:[{title:"Read the output",body:"Levels 1 and 2 are in place; levels 3 and 4 are missing; level 5 is requested."},{title:"Decide",body:"Each level is sustained by the one below it, so standardized work comes next; kanban now would backfire."}],final:"Build standardized work before going higher → answer **D**",whyWrong:["Incorrect — kanban needs kaizen beneath it, and kaizen needs standardized work.","Incorrect — the visual factory depends on 5S; dropping the audits would undermine it.","Incorrect — no level can be skipped; kanban is sustained by kaizen.",""],bookRef:"Book pp. 502, 512"},{id:"sv-5-493",phase:5,topic:"5.1.1",qtype:"output",difficulty:2,stem:`Completion of a layered 5S audit programme over the last six weeks is shown.

\`\`\`
Layered 5S audits – NOC equipment room (last 6 weeks)
Layer         Who                 Planned   Done
Self-check    Shift engineer      30        30
Team audit    Team lead            6         2
Cross-audit   Other-area manager   2         2
\`\`\`

Which conclusion is CORRECT?`,options:["The weekly team-audit layer is the weak point and needs attention","The self-check layer is the weak point, because it has the most audits planned","The cross-audit layer is the weak point, because it happens least often","All layers are working, because every layer has some audits done"],answer:0,hint:"Compare done with planned for each layer.",steps:[{title:"Read the output",body:"Self-check 30 of 30, cross-audit 2 of 2, team audit only 2 of 6."},{title:"Decide",body:"The team-lead layer is being skipped, so it is the weak point to fix, for example by putting it into leader standard work."}],final:"Team audit 2 of 6 = weak layer → answer **A**",whyWrong:["","Incorrect — the self-checks were all done (30 of 30).","Incorrect — the cross-audits were all done (2 of 2); low frequency is by design.","Incorrect — the team audit was done only 2 times out of 6, so that layer is failing."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-494",phase:5,topic:"5.1.1",qtype:"output",difficulty:2,stem:`A service desk's weekly queue-hygiene report is shown.

\`\`\`
Queue hygiene – Service desk, week 31      Target = 95%
Rule                                Compliance
Ticket has an assignment group          99%
Category from the controlled list       98%
Updated within the last 5 days          71%
\`\`\`

Which conclusion is CORRECT?`,options:["All rules meet target, so no action is needed","The five-day update rule is not being held and needs a countermeasure","The category rule is the weakest and needs attention first","The report shows the queue should be deleted and restarted"],answer:1,hint:"Compare each rule's compliance with the 95% target.",steps:[{title:"Read the output",body:"Assignment group 99% and category 98% are above target; update-within-5-days is 71%."},{title:"Decide",body:"Only the update rule is failing, so the response targets that rule and asks why it is not being held."}],final:"Update rule at 71% needs a countermeasure → answer **B**",whyWrong:["Incorrect — 71% is well below the 95% target.","","Incorrect — the category rule is at 98%, above target.","Incorrect — a purge is a one-off Sort; the issue is one rule that is not being held."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-495",phase:5,topic:"5.1.1",qtype:"output",difficulty:1,stem:`During a walk-through, newcomers were asked whether they could tell **within 10 seconds** if each area was at standard.

\`\`\`
10-second test – Field depot
Area           Newcomer could tell?   Notes
Van bays       Yes                    Floor-marked, labelled
Tool wall      Yes                    Shadow outlines
Spares cage    No                     No labels or min/max marks
Returns desk   Yes                    Colour-coded trays
\`\`\`

Which area MOST needs visual controls?`,options:["Van bays","Tool wall","Spares cage","Returns desk"],answer:2,hint:"Which area failed the test, and why?",steps:[{title:"Read the output",body:"Only the spares cage failed: it has no labels and no min/max marks."},{title:"Decide",body:"That area needs visual controls so a deviation is obvious at a glance."}],final:"Spares cage failed the 10-second test → answer **C**",whyWrong:["Incorrect — the van bays passed, with floor marking and labels.","Incorrect — the tool wall passed, with shadow outlines.","","Incorrect — the returns desk passed, with colour-coded trays."],bookRef:"Book pp. 507–508"},{id:"sv-5-496",phase:5,topic:"5.1.1",qtype:"output",difficulty:2,stem:`A 5S pilot area has been audited for three months.

\`\`\`
5S pilot – Regional NOC store (monthly audit, target 80%)
Month          1     2     3
Pilot store   84%   86%   88%
Other stores  not started
\`\`\`

What is the BEST next step, in line with the book?`,options:["Launch 5S in every remaining store on the same day","Stop auditing the pilot store, since it has reached target","Restart the pilot from Sorting to confirm the results","Spread 5S step by step to the next area, using the pilot's standards"],answer:3,hint:"The book: start in a pilot area, then spread step by step.",steps:[{title:"Read the output",body:"The pilot has been above target for three months and is still improving; no other store has started."},{title:"Decide",body:"The pilot has proved the standard, so spread it to the next area while keeping the pilot's audits running."}],final:"Pilot stable → spread step by step → answer **D**",whyWrong:["Incorrect — the book recommends spreading step by step, not all at once.","Incorrect — stopping audits removes the control and invites a slide.","Incorrect — the pilot is stable and improving; restarting wastes the gain.",""],bookRef:"Book p. 503"},{id:"sv-5-497",phase:5,topic:"5.1.1",qtype:"true-false",difficulty:1,stem:"According to the book, the Lean tools in the pyramid may be used only during the Control phase. True or False?",options:["True","False"],answer:1,hint:"When does the book say Lean controls can be used?",steps:[{title:"Key idea",body:"The book introduces Lean controls in Control but says they can be used at **any time**: before, during or at the end of a project."},{title:"Apply",body:"'Only during Control' is therefore false."}],final:"Usable at any time → False → answer **B**",whyWrong:["Incorrect — the book says the Lean tools can be used before, during or at the end of a project.",""],bookRef:"Book p. 501"},{id:"sv-5-498",phase:5,topic:"5.1.1",qtype:"sequence",difficulty:2,stem:`Put the book's Sorting procedure in order:

- **P** — Remove unknown items that nobody used during the set period
- **Q** — Start in one area
- **R** — Dispose of useless items immediately and tag those that cannot go at once
- **S** — Place each item in the useful, useless or unknown group`,options:["Q → S → R → P","S → Q → R → P","Q → R → S → P","Q → S → P → R"],answer:0,hint:"Choose the area → group → act on useless → act on unknown after the hold.",steps:[{title:"Key idea",body:"The book: start in one area, sort everything into useful / useless / unknown, dispose of useless items at once (tagging what cannot go yet), and remove unknown items after a set period if unused."},{title:"Apply",body:"Q → S → R → P."}],final:"Q → S → R → P → answer **A**",whyWrong:["","Incorrect — items cannot be grouped before an area is chosen.","Incorrect — useless items cannot be removed before the items are grouped.","Incorrect — unknown items are removed only after the hold period, so that step comes last."],bookRef:"Book p. 504"},{id:"sv-5-499",phase:5,topic:"5.1.1",qtype:"sequence",difficulty:2,stem:`Put these steps for running 5S as a control in order:

- **P** — Compare the score with the response-rule trigger
- **Q** — Write the standard and post a photo of the area at standard
- **R** — Assign a countermeasure owner when the trigger fires
- **S** — Audit the area against the standard with a scored checklist`,options:["S → Q → P → R","Q → S → P → R","Q → P → S → R","Q → S → R → P"],answer:1,hint:"Standard → measure → compare → respond.",steps:[{title:"Key idea",body:"A control needs a standard, a measurement against it, a decision rule and a response."},{title:"Apply",body:"Write the standard (Q) → audit (S) → compare with the trigger (P) → assign an owner (R)."}],final:"Q → S → P → R → answer **B**",whyWrong:["Incorrect — an audit needs a standard to audit against, so the standard comes first.","","Incorrect — there is no score to compare until the audit has been done.","Incorrect — an owner is assigned only after the comparison shows the trigger has fired."],bookRef:"Syllabus 5.1.1"},{id:"sv-5-500",phase:5,topic:"5.1.1",qtype:"sequence",difficulty:3,stem:`A service desk applies 5S to its ticket queue. Put these activities in 5S order:

- **P** — Agree hygiene rules for every ticket (owner, category list, update within 5 days)
- **Q** — Close duplicate and obsolete tickets
- **R** — Score the queue weekly against the rules and post the result
- **S** — Give each request type one fixed queue and naming format
- **T** — Clean out stale data and bring every ticket's status up to date`,options:["S → Q → T → P → R","Q → T → S → P → R","Q → S → T → P → R","Q → S → T → R → P"],answer:2,hint:"Match each activity to its S, then use the 5S order.",steps:[{title:"Match",body:"Q = Sorting, S = Straightening, T = Shining, P = Standardizing, R = Sustaining."},{title:"Order",body:"Sort → Straighten → Shine → Standardize → Sustain gives Q → S → T → P → R."}],final:"Q → S → T → P → R → answer **C**",whyWrong:["Incorrect — a fixed home is given only after unneeded tickets are removed.","Incorrect — Straightening comes before Shining.","","Incorrect — rules (Standardizing) must exist before they can be scored (Sustaining)."],bookRef:"Book p. 503"},{id:"sv-5-501",phase:5,topic:"5.1.1",qtype:"sequence",difficulty:2,stem:`A store's 5S audit has fallen below target twice in a row. Put the response in order:

- **P** — Ask why the standard is not being held
- **Q** — Check the next audit to confirm the countermeasure worked
- **R** — Review the per-S scores to find the weak S
- **S** — Put the countermeasure in place, with an owner`,options:["P → R → S → Q","R → S → P → Q","S → R → P → Q","R → P → S → Q"],answer:3,hint:"Locate → understand → act → check.",steps:[{title:"Key idea",body:"Treat a sliding audit like any problem: locate the weak S, find the cause, act with an owner, then check the result."},{title:"Apply",body:"R → P → S → Q."}],final:"R → P → S → Q → answer **D**",whyWrong:["Incorrect — you need to know which S is weak before asking why it is failing.","Incorrect — the countermeasure should follow the root cause, not come before it.","Incorrect — acting first and diagnosing later is tampering.",""],bookRef:"Syllabus 5.1.1"},{id:"sv-5-502",phase:5,topic:"5.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Kanban is the technique used to [?] products and material through a Lean system.`,options:["batch","pull","push","schedule"],answer:1,hint:"Kanban works on actual downstream consumption, not on a forecast.",steps:[{title:"Key idea",body:"The book describes kanban as the technique used to **pull** products and material through a Lean system."},{title:"Eliminate look-alikes",body:"Push and schedule-driven release are the opposite logic; batching is not what the card controls."}],final:"Kanban pulls material → answer **B**",whyWrong:["Incorrect — batching moves work in large lots; kanban keeps quantities standard and small.","","Incorrect — push releases work to a forecast; kanban is the opposite, a pull signal.","Incorrect — scheduling to a plan is how push systems release work, not how kanban works."],bookRef:"Book p. 511"},{id:"sv-5-503",phase:5,topic:"5.1.2",qtype:"output",difficulty:3,stem:`Two stores of the same operator were compared over eight weeks.

\`\`\`
Store comparison – ONT units, 8 weeks
                           Store A            Store B
Replenishment trigger      Weekly forecast    Empty bin returned
Average stock (units)      410                95
Stock-out days             3                  2
Units scrapped (obsolete)  37                 0
\`\`\`

Based on the output, which conclusion is CORRECT?`,options:["Store B runs a pull system and holds far less stock without more stock-outs","Store A runs a pull system, because it reorders on a fixed weekly cycle","Store B runs a push system, because its bins authorise the replenishment","Store A's higher stock shows that it has the better-sized kanban loop"],answer:0,hint:"Identify the trigger in each store, then compare stock and stock-outs.",steps:[{title:"Read the trigger",body:"Store A replenishes to a **forecast** (push). Store B replenishes when an **empty bin** comes back (pull, a kanban signal)."},{title:"Read the results",body:"Store B holds 95 units against 410, scraps none against 37, and has no more stock-out days (2 against 3)."},{title:"Decide",body:"The pull store carries much less inventory without more stock-outs."}],final:"Empty-bin trigger = pull; lower stock, no more stock-outs → answer **A**",whyWrong:["","Incorrect — reordering to a weekly forecast is push; a fixed cycle is not a pull signal.","Incorrect — a returned empty bin is a consumption signal, which is the definition of pull.","Incorrect — Store A has no kanban loop; its high stock and scrap are typical of push."],bookRef:"Book p. 511"},{id:"sv-5-504",phase:5,topic:"5.1.2",qtype:"best-action",difficulty:3,stem:"A planner sets up withdrawal kanbans between a moulding cell and the assembly line, so that the line takes housings from moulding only as it uses them, and WIP between the two processes is regulated. Was this an appropriate action?",options:["Yes, because withdrawal kanbans pull material from a supplying process and regulate WIP between them","Yes, because withdrawal kanbans tell the moulding cell to produce finished goods for stock","No, because withdrawal kanbans may only be used with external suppliers","No, because WIP between two processes should be set by the weekly forecast"],answer:0,hint:"Withdrawal (incoming-material) kanban: supplying department, internal or external; regulates WIP.",steps:[{title:"Key idea",body:"The book's incoming-material (withdrawal, inter-process) kanban gets material from a **supplying department, internal or external**, and regulates WIP between processes."},{title:"Apply",body:"Moulding supplies the line; the line withdraws only what it uses. This is exactly the withdrawal kanban's purpose."}],final:"Withdrawal kanban between two internal processes is appropriate → answer **A**",whyWrong:["","Incorrect — starting production of finished goods is the job of a signal kanban or P.I.K., not a withdrawal kanban.","Incorrect — the book says the supplying department can be internal or external.","Incorrect — setting WIP by forecast is push logic, which kanban replaces."],bookRef:"Book p. 511"},{id:"sv-5-505",phase:5,topic:"5.1.2",qtype:"best-action",difficulty:2,stem:"A provisioning team works in a push style: each morning managers hand out new orders based on the sales forecast, and half-finished orders pile up at the Test step. What is the BEST step toward a pull system?",options:["Hand out more orders each morning, so the Test step is never idle","Set a WIP limit for each step, so a step takes new work only when it has a free slot","Add a second inspection at Test, so the backlog is cleared faster","Lengthen the forecast horizon from one day to one week"],answer:1,hint:"Pull replaces the forecast trigger with a downstream signal.",steps:[{title:"Key idea",body:"To move from push to pull, work must start on a **downstream signal**, not a forecast. WIP limits make a free slot that signal."},{title:"Eliminate look-alikes",body:"More orders, extra inspection and a longer forecast all keep the push logic."}],final:"WIP limits turn the board into a pull system → answer **B**",whyWrong:["Incorrect — releasing more work pushes harder and grows the pile at Test.","","Incorrect — inspection adds checking capacity; it does not change the push trigger.","Incorrect — a longer forecast is still a forecast; work would still be pushed."],bookRef:"Book p. 511"},{id:"sv-5-506",phase:5,topic:"5.1.2",qtype:"concept",difficulty:2,stem:"Which statement about pull systems is CORRECT?",options:["Pull systems need larger safety stocks than push systems","In a pull system, the first step sets the pace for all later steps","The pace of the whole chain is set by the downstream customer's consumption","Pull systems suit manufacturing only and cannot be used in service work"],answer:2,hint:"Where does the signal start in a pull chain?",steps:[{title:"Key idea",body:"In pull, each step replaces only what the next step has used, so **downstream consumption** paces the chain."},{title:"Eliminate look-alikes",body:"Pull lowers stock, is not paced by the first step and applies to service work as well."}],final:"Downstream consumption sets the pace → answer **C**",whyWrong:["Incorrect — pull systems reduce stock; large safety stocks are typical of push.","Incorrect — this is push thinking; in pull, the customer end sets the pace and signals travel upstream.","","Incorrect — kanban boards with WIP limits are widely used in IT and service work."],bookRef:"Book p. 511"},{id:"sv-5-507",phase:5,topic:"5.1.2",qtype:"concept",difficulty:1,stem:"In a container-based kanban loop, when is replenishment of a container triggered?",options:["When the container is about half used, as a safety margin","When the weekly replenishment schedule says it is due","When the storekeeper judges that stock looks low","When a standard container has been emptied and its signal is released"],answer:3,hint:"The empty container itself is the signal.",steps:[{title:"Key idea",body:"The book says a kanban can be a card or a physical signal such as an **empty container**. Using up a standard container releases the signal."},{title:"Eliminate look-alikes",body:"Partial-use triggers, schedules and judgement are not consumption signals of a fixed quantity."}],final:"Empty standard container = replenishment signal → answer **D**",whyWrong:["Incorrect — the safety margin is built into the number of containers, not into partial triggers.","Incorrect — a schedule is a push trigger; kanban responds to consumption.","Incorrect — personal judgement is not a signal; the empty container is the standard trigger.",""],bookRef:"Book pp. 511–512"},{id:"sv-5-508",phase:5,topic:"5.1.2",qtype:"concept",difficulty:1,stem:"In a **push** system, where does work-in-process typically pile up?",options:["In front of the slowest step","At the very first step of the process","Evenly in front of every step","Only in the finished-goods store"],answer:0,hint:"Pushed work arrives faster than the bottleneck can process it.",steps:[{title:"Key idea",body:"In push, each step works to a forecast and passes work on whether or not the next step is ready, so **queues build in front of the slowest step** and lead time grows."},{title:"Eliminate look-alikes",body:"Push piles are uneven and sit at the bottleneck, not at the start, evenly or only at the end."}],final:"Push → queues at the slowest step → answer **A**",whyWrong:["","Incorrect — the first step keeps releasing work forward, so its own queue is not where work builds.","Incorrect — queues are not even; they build where capacity is lowest.","Incorrect — WIP also builds inside the process, not only at the end."],bookRef:"Syllabus 5.1.2"},{id:"sv-5-509",phase:5,topic:"5.1.2",qtype:"concept",difficulty:2,stem:"Which statement about inventory in a **push** system is CORRECT?",options:["Large stock between steps makes defects visible at once","Large stock between steps can hide defects until many units are affected","Stock between steps is capped by the number of kanbans","Stock between steps falls as the forecast horizon grows"],answer:1,hint:"What does a big pile of WIP do to a problem upstream?",steps:[{title:"Key idea",body:"In push, uncapped inventory builds up. A defect made upstream sits in the pile and is found only when the stock is used, by which time many units carry it."},{title:"Eliminate look-alikes",body:"Visibility at once and capping by cards are features of pull, not push."}],final:"Push stock hides defects → answer **B**",whyWrong:["Incorrect — the opposite: piles of stock delay the discovery of a defect.","","Incorrect — cards capping stock describes a pull (kanban) system.","Incorrect — longer forecasts usually push more work out and raise stock."],bookRef:"Syllabus 5.1.2"},{id:"sv-5-510",phase:5,topic:"5.1.2",qtype:"scenario",difficulty:3,stem:"On a set-top-box test line, an operator presses a button that lights a lamp and stops the line whenever a unit fails its test. A colleague calls this lamp 'our kanban'. What is the signal correctly called?",options:["A signal kanban, because it tells the line to begin work","A withdrawal kanban, because it pulls material from a supplier","An andon, because it signals an abnormality and stops work","A P.I.K., because it keeps finished stock at a minimum"],answer:2,hint:"Does the signal authorise work, or stop it because something is wrong?",steps:[{title:"Key idea",body:"A kanban is a signal to **begin** work or to move material. A lamp that stops the line on a fault is an **andon**, an abnormality signal."},{title:"Apply",body:"The lamp stops work after a failed test, so it is an andon."},{title:"Eliminate look-alikes",body:"Signal, withdrawal and P.I.K. kanbans all authorise making or moving."}],final:"Stop-on-fault lamp = andon, not kanban → answer **C**",whyWrong:["Incorrect — a signal kanban starts production; this lamp stops it.","Incorrect — a withdrawal kanban authorises moving material; this lamp reports a fault.","","Incorrect — a P.I.K. controls finished-goods inventory; this lamp has nothing to do with stock."],bookRef:"Book p. 511"},{id:"sv-5-511",phase:5,topic:"5.1.2",qtype:"output",difficulty:3,stem:`Work-in-process was counted at each step of a repair line that releases jobs to a weekly forecast.

\`\`\`
WIP count – Router repair line (push release)
Step        Capacity/day   Jobs waiting in front
Diagnose        60                 3
Repair          55                 4
Test            30                46
Pack            70                 2
\`\`\`

Which conclusion is CORRECT?`,options:["Work piles up evenly, so the forecast is correct","Pack is the bottleneck, because it waits the least","Diagnose should release more jobs to keep Test busy","Work piles up in front of Test, the slowest step, as expected in a push system"],answer:3,hint:"Read the step with the lowest capacity and the longest queue.",steps:[{title:"Read the output",body:"Test has the lowest capacity (30 a day) and the longest queue (46 jobs). The other steps have 2–4 waiting."},{title:"Decide",body:"Pushed work builds in front of the slowest step. A pull system with WIP limits would stop more work being released than Test can take."}],final:"Pile-up at the slowest step (Test) = push symptom → answer **D**",whyWrong:["Incorrect — 46 jobs at Test against 2–4 elsewhere is far from even.","Incorrect — Pack has the highest capacity; a short queue there is not a bottleneck sign.","Incorrect — releasing more work would grow the pile at Test; pull or WIP limits would cap it.",""],bookRef:"Syllabus 5.1.2"},{id:"sv-5-512",phase:5,topic:"5.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In a pull system, a step produces only when the [?] step signals that it has used something.`,options:["downstream","parallel","previous","upstream"],answer:0,hint:"The customer of the work sends the pull signal.",steps:[{title:"Key idea",body:"In pull, the **downstream** step (the internal customer) signals consumption; the upstream step then makes or moves a replacement."},{title:"Eliminate look-alikes",body:"Previous and upstream steps are suppliers; parallel steps are not customers."}],final:"Downstream step sends the signal → answer **A**",whyWrong:["","Incorrect — a parallel step is not the customer of the work, so it does not give the signal.","Incorrect — the previous step is the supplier; it receives the signal rather than sending it.","Incorrect — upstream steps are suppliers; the signal flows to them, not from them."],bookRef:"Book p. 511"},{id:"sv-5-513",phase:5,topic:"5.1.2",qtype:"true-false",difficulty:1,stem:"Push systems usually give shorter and more predictable lead times than pull systems. True or False?",options:["True","False"],answer:1,hint:"More work waiting in the system means a longer wait for each item.",steps:[{title:"Key idea",body:"In push, WIP is uncapped and builds at bottlenecks, so items wait longer and lead times vary."},{title:"Apply",body:"Pull caps WIP, so lead time is shorter and more predictable. The statement is false."}],final:"Push lead time is longer and more variable → False → answer **B**",whyWrong:["Incorrect — uncapped WIP in push systems makes lead times long and variable; capping WIP with pull shortens them.",""],bookRef:"Syllabus 5.1.2"},{id:"sv-5-514",phase:5,topic:"5.1.2",qtype:"concept",difficulty:2,stem:"Many texts summarise the book's two kanban categories as **production** and **withdrawal** kanbans. Which describes the difference?",options:["A production kanban authorises making a quantity; a withdrawal kanban authorises moving it","A production kanban authorises moving a quantity; a withdrawal kanban authorises making it","A production kanban records defects; a withdrawal kanban records stock levels","A production kanban is used with suppliers; a withdrawal kanban only inside one process"],answer:0,hint:"Finished goods → make; incoming material → withdraw (move).",steps:[{title:"Key idea",body:"Finished-goods (signal, P.I.K.) kanbans tell a process to **make**; incoming-material (withdrawal) kanbans tell someone to **move** material from a supplying process."},{title:"Eliminate look-alikes",body:"The reversed options swap the roles; the record-keeping option misreads the purpose of a kanban."}],final:"Production = make; withdrawal = move → answer **A**",whyWrong:["","Incorrect — this reverses the two roles.","Incorrect — neither card is a defect or stock record; both authorise work.","Incorrect — reversed again: withdrawal (incoming material) is the supplier-facing kanban."],bookRef:"Book p. 511"},{id:"sv-5-515",phase:5,topic:"5.1.2",qtype:"scenario",difficulty:3,stem:"In a refurbishment plant, a card travels with each tray of finished set-top boxes. When packing uses a tray, the card goes back to the refurbishment cell, which then refurbishes **one more tray**. What does this card authorise?",options:["Moving — it is a withdrawal (incoming-material) kanban","Making — it is a finished-goods (production) kanban","Stopping — it is an andon signal","Recording — it is a check sheet for defects"],answer:1,hint:"Follow the card: who acts when it comes back?",steps:[{title:"Key idea",body:"A finished-goods kanban tells a process to **produce**; a withdrawal kanban tells someone to **move** material from a supplier."},{title:"Apply",body:"The returning card makes the cell refurbish one more tray, so it authorises **making**."},{title:"Eliminate look-alikes",body:"Moving, stopping and recording are the jobs of other signals or tools."}],final:"Card triggers production = finished-goods kanban → answer **B**",whyWrong:["Incorrect — the card goes back to the producing cell to start work, not to fetch material from a supplier.","","Incorrect — an andon signals an abnormality; this card starts normal production.","Incorrect — a check sheet records data; this card triggers work."],bookRef:"Book p. 511"},{id:"sv-5-516",phase:5,topic:"5.1.2",qtype:"not-except",difficulty:2,stem:"Which is NOT a typical symptom of a push system?",options:["Inventory piles up in front of the slowest step","Defects stay hidden in stock for a long time","WIP is capped by the number of cards in circulation","Lead time is long and varies widely"],answer:2,hint:"Three options describe push; the outsider describes pull.",steps:[{title:"Key idea",body:"Push systems release work to a forecast, so WIP is uncapped: it piles at bottlenecks, hides defects and stretches lead time."},{title:"Apply",body:"A WIP cap set by cards is a **pull** feature, so it is NOT a push symptom."}],final:"Card-capped WIP is pull → NOT a push symptom → answer **C**",whyWrong:["Incorrect — piles at the slowest step are a classic push symptom.","Incorrect — hidden defects under stock are a classic push symptom.","","Incorrect — long, variable lead times are a classic push symptom."],bookRef:"Syllabus 5.1.2"},{id:"sv-5-517",phase:5,topic:"5.1.2",qtype:"not-except",difficulty:2,stem:"Which is NOT a feature of the book's Type 2 (incoming-material) kanban?",options:["It is used to get material from a supplying department","It regulates WIP between two processes","Its supplying department can be internal or external","It is posted at the end of a processing area to signal production to begin"],answer:3,hint:"Type 2 brings material in; Type 1 starts production.",steps:[{title:"Key idea",body:"Type 2 (withdrawal, inter-process, supplier) kanban gets material from a supplying department, internal or external, and regulates WIP."},{title:"Apply",body:"Posting at the end of a processing area to start production describes the **signal kanban**, a Type 1 finished-goods kanban."}],final:"Signal-to-produce is Type 1 → NOT Type 2 → answer **D**",whyWrong:["Incorrect — getting material from a supplying department is the purpose of Type 2.","Incorrect — regulating WIP between processes is a Type 2 feature.","Incorrect — the book says the supplier can be internal or external.",""],bookRef:"Book p. 511"},{id:"sv-5-518",phase:5,topic:"5.1.2",qtype:"sequence",difficulty:3,stem:`A line uses a two-card kanban system (production cards and withdrawal cards). Put the steps of one cycle in order:

- **P** — The line uses up a container and its withdrawal card is detached
- **Q** — A handler takes the withdrawal card to the supplying process's store
- **R** — The full container, now carrying the withdrawal card, is moved to the line
- **S** — At the store, the production card is removed from a full container and posted, so the supplier makes a replacement`,options:["P → Q → S → R","P → S → Q → R","Q → P → S → R","P → Q → R → S"],answer:0,hint:"Consumption → move signal goes upstream → swap cards at the store → material moves downstream.",steps:[{title:"Key idea",body:"The withdrawal card authorises **moving**; the production card authorises **making**. The swap happens at the supplier's store."},{title:"Apply",body:"Line empties a container (P) → withdrawal card to the store (Q) → production card posted, so a replacement is made (S) → full container moves to the line (R)."}],final:"P → Q → S → R → answer **A**",whyWrong:["","Incorrect — the supplier cannot be told to replace a container before anyone has come to collect one.","Incorrect — there is no withdrawal card to carry until the line has used up a container.","Incorrect — the production card is swapped for the withdrawal card at the store, before the container leaves."],bookRef:"Book p. 511"},{id:"sv-5-519",phase:5,topic:"5.1.2",qtype:"output",difficulty:1,stem:`A Black Belt lists what starts work in four processes.

\`\`\`
Process                   What starts the next batch
Cable cutting             Monthly MRP plan
ONT configuration         Supervisor's daily target
SIM packing               Empty tray returned from the shop floor
Router refurbishment      Quarterly sales forecast
\`\`\`

Which process operates as a pull system?`,options:["Cable cutting","SIM packing","ONT configuration","Router refurbishment"],answer:1,hint:"Pull = started by actual downstream consumption.",steps:[{title:"Read the output",body:"Only SIM packing is triggered by something used downstream: an empty tray coming back."},{title:"Decide",body:"Plans, targets and forecasts are push triggers; the returned empty tray is a kanban signal."}],final:"Empty tray trigger = pull → answer **B**",whyWrong:["Incorrect — a monthly plan releases work to a schedule, which is push.","","Incorrect — a daily target pushes work regardless of downstream use.","Incorrect — a sales forecast is a push trigger."],bookRef:"Book p. 511"},{id:"sv-5-520",phase:5,topic:"5.1.2",qtype:"concept",difficulty:1,stem:"Why does an empty container work well as a kanban signal?",options:["It records how many defects the last container held","It lets the storekeeper refill it with any quantity that fits","The empty space itself shows that replenishment is needed, with no paperwork","It replaces the need for a standard quantity per container"],answer:2,hint:"A good kanban needs no explanation to act on it.",steps:[{title:"Key idea",body:"The book allows a physical signal such as an **empty container**. Its emptiness is a visual signal anyone can read, so no form is needed."},{title:"Eliminate look-alikes",body:"It does not record defects, and the quantity per container must stay standard."}],final:"Empty container = visual signal, no paperwork → answer **C**",whyWrong:["Incorrect — a container signal carries no defect data; quality records do that.","Incorrect — the book insists the quantity per container is standard, not 'whatever fits'.","","Incorrect — the signal only works because each container holds a standard quantity."],bookRef:"Book pp. 511–512"},{id:"sv-5-521",phase:5,topic:"5.1.2",qtype:"concept",difficulty:2,stem:"What does **inter-process** mean when the book uses it to describe a kanban?",options:["Inside a single process: the card controls that process's own production","Between two shifts working in the same process","Between the process and the customer's invoice system","Between two processes: material moves from a supplying process to a using one"],answer:3,hint:"Inter = between (like 'international'); intra = within.",steps:[{title:"Key idea",body:"The book calls the incoming-material (withdrawal) kanban **inter-process**: it works **between** a supplying department and a using one."},{title:"Eliminate look-alikes",body:"Intra-process means within one process (finished goods); shifts and invoices are not the point."}],final:"Inter-process = between supplying and using processes → answer **D**",whyWrong:["Incorrect — 'inside a single process' is intra-process, the finished-goods kanban.","Incorrect — shift handovers are not what the term describes.","Incorrect — kanbans control material and production, not invoicing.",""],bookRef:"Book p. 511"},{id:"sv-5-522",phase:5,topic:"5.1.2",qtype:"concept",difficulty:3,stem:"Both the signal kanban and the P.I.K. are finished-goods kanbans. What distinguishes the **P.I.K.**?",options:["It gives finer control: it is posted as inventory is depleted, so only the minimum level is kept","It is posted at the end of the processing area to signal that production may begin","It is used to get material from a supplying department","It regulates WIP between two separate processes"],answer:0,hint:"Same category, different precision.",steps:[{title:"Key idea",body:"Book: the **signal kanban** is posted at the end of the processing area to start production. The **P.I.K.** gives finer inventory control: posted as inventory is depleted so only the minimum allowable level is kept."},{title:"Eliminate look-alikes",body:"Supplier material and inter-process WIP belong to the Type 2 kanban."}],final:"P.I.K. = finer, minimum-level control → answer **A**",whyWrong:["","Incorrect — that is the book's description of the signal kanban, the coarser of the two.","Incorrect — getting material from a supplier is the Type 2 incoming-material role.","Incorrect — regulating WIP between processes is the withdrawal (Type 2) role."],bookRef:"Book p. 511"},{id:"sv-5-523",phase:5,topic:"5.1.2",qtype:"scenario",difficulty:2,stem:"A hospital pharmacy refills a ward's medicine cabinet only when a nurse scans the barcode on an emptied tray; the scan sends a message to the pharmacy. Which system is this?",options:["A push system, because the pharmacy prepares the refill","A pull system using an electronic kanban signal","A forecast-based replenishment system","A mistake-proofing (poka-yoke) system"],answer:1,hint:"Is the refill triggered by consumption, and does the signal have to be a card?",steps:[{title:"Key idea",body:"A kanban can be a card, an empty container or an electronic message, as long as **consumption** triggers it."},{title:"Apply",body:"The emptied tray is scanned and the message pulls a refill, so this is pull with an electronic kanban."}],final:"Consumption-triggered scan = electronic kanban (pull) → answer **B**",whyWrong:["Incorrect — the pharmacy acts only after the ward signals use; that is pull, not push.","","Incorrect — no forecast is involved; the emptied tray triggers the refill.","Incorrect — the scan is a replenishment signal, not a device that prevents errors."],bookRef:"Book p. 511"},{id:"sv-5-524",phase:5,topic:"5.1.2",qtype:"statements",difficulty:2,stem:`Which statements about kanban cards are CORRECT?

1. A card shows the item and a standard quantity per container.
2. Each card in a loop is numbered, for example 'card 3 of 8', so that lost cards are noticed.
3. The storekeeper decides the quantity on the card each time it is used.
4. A card is valid only after the planning department has scheduled it.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"A kanban must carry enough fixed information to act on without asking.",steps:[{title:"Check each",body:"1 true (item and standard quantity). 2 true (numbering exposes lost cards). 3 false (the book insists the quantity is standard). 4 false (scheduling is push logic)."},{title:"Decide",body:"The true statements are 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: the quantity per card must be standard.","Incorrect — statements 3 and 4 are both false.","Incorrect — statement 4 is false: consumption, not planning, makes a card active."],bookRef:"Book p. 512"},{id:"sv-5-525",phase:5,topic:"5.1.2",qtype:"concept",difficulty:2,stem:"In a kanban loop, in which directions do the **signal** and the **material** travel?",options:["The signal travels downstream; the material travels upstream","Both the signal and the material travel downstream","The signal travels upstream; the material travels downstream","Both the signal and the material travel upstream"],answer:2,hint:"The customer asks (signal back), the supplier delivers (material forward).",steps:[{title:"Key idea",body:"The downstream step uses material and sends the kanban **back upstream**; the supplying step then sends material **forward downstream**."},{title:"Eliminate look-alikes",body:"Any option with the signal moving downstream describes push logic."}],final:"Signal upstream, material downstream → answer **C**",whyWrong:["Incorrect — this reverses both directions.","Incorrect — a downstream signal would be push: the supplier telling the customer to take work.","","Incorrect — material flows to the customer, which is downstream."],bookRef:"Book p. 511"}];export{e as items};
